var TAG = "[Видеонаблюдение] ";

// ═══════════════════════════════════════════════════════════════════════════
// ТОЧКА ВХОДА — изменение мастер-выключателя и старт
// ═══════════════════════════════════════════════════════════════════════════
function trigger(source, value, variables, options, context) {
  try {
    variables.opts = options;
    variables.masterUuid = String(source.getService().getUUID());
    var on = toBool(value);
    if (on === null) on = (readBool(variables.masterUuid, HC.On) === true);

    if (!variables.inited) {
      // Старт: отвечаем хабу сразу, инициализация — отдельно
      setTimeout(function () {
        try {
          if (!variables.inited) init(on, variables, options);
          setupSubscription(variables);
          setupCron(variables);
          tick(variables);
        } catch (e) { console.error(TAG + "старт: " + e.message); }
      }, 500);
      return;
    }
    if (on !== variables.masterOn) onMasterChange(on, variables, options, "мастер-выключатель");
    setupSubscription(variables);
    setupCron(variables);
    tick(variables);
  } catch (e) {
    console.error(TAG + "trigger: " + e.message);
  }
}

function init(on, variables, options) {
  var now = Date.now();
  variables.inited = true;
  variables.masterOn = on;
  variables.dl = { arrival: 0, verify: 0, homeOnline: 0, floodOn: zeros(CAM_COUNT), floodOff: zeros(CAM_COUNT) };
  variables.mm = { since: 0, reported: false };
  var s = readAll(options, variables.masterUuid);
  variables.prev = s;
  variables.awaySince = (s.away === true) ? now : 0;
  variables.cams = [];
  for (var i = 0; i < s.cams.length; i++) variables.cams.push({ on: s.cams[i], since: now, alerted: false });

  log(options, "старт: мастер " + (on ? "ВКЛ" : "ВЫКЛ") + ", режим " + modeTxt(s.sec) +
      ", в сети: " + (namesWhere(options, s.cams, true).join(", ") || "нет"));
  if (s.away === true && !on && options.awayCamerasOn) setMaster(true, variables, options, "старт в режиме «Не дома»");
}

// ═══════════════════════════════════════════════════════════════════════════
// МАСТЕР
// ═══════════════════════════════════════════════════════════════════════════
function onMasterChange(on, variables, options, why) {
  variables.masterOn = on;
  variables.mm = { since: 0, reported: false };
  var vs = intOr(options.offVerifySec, 300);
  variables.dl.verify = (!on && vs > 0) ? Date.now() + vs * 1000 : 0;
  if (on) variables.dl.homeOnline = 0;
  log(options, "мастер → " + (on ? "ВКЛ" : "ВЫКЛ") + " (" + why + ")");
  setPower(on, options);
}

function setMaster(on, variables, options, why) {
  if (variables.masterOn === on) return;
  var svc = getService(variables.masterUuid);
  onMasterChange(on, variables, options, why);   // сначала состояние — trigger от setValue будет пропущен
  if (!svc) { console.warn(TAG + "мастер-выключатель не найден"); return; }
  try { svc.getCharacteristic(HC.On).setValue(on === true); }
  catch (e) { console.error(TAG + "мастер setValue: " + e.message); }
}

function setPower(on, options) {
  var list = powerUuids(options);
  for (var i = 0; i < list.length; i++) {
    if (!list[i]) continue;
    try {
      var svc = getService(list[i]);
      if (!svc) { console.warn(TAG + "питание камеры " + (i + 1) + " не найдено"); continue; }
      var c = svc.getCharacteristic(HC.On);
      if (toBool(c.getValue()) !== on) c.setValue(on === true);
    } catch (e) {
      console.error(TAG + "питание камеры " + (i + 1) + ": " + e.message);
    }
  }
}

function setLight(uuid, on, options, why) {
  uuid = trimStr(uuid);
  if (!uuid) return;
  try {
    var svc = getService(uuid);
    if (!svc) return;
    var c = svc.getCharacteristic(HC.On);
    if (toBool(c.getValue()) === on) return;
    c.setValue(on === true);
    log(options, "прожектор " + svcName(uuid) + " → " + (on ? "ВКЛ" : "ВЫКЛ") + " (" + why + ")");
  } catch (e) {
    console.error(TAG + "прожектор: " + e.message);
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// ПОДПИСКА И ТАЙМЕР
// ═══════════════════════════════════════════════════════════════════════════
function setupSubscription(variables) {
  if (variables.sub) return;
  try {
    variables.sub = Hub.subscribeWithCondition("", "",
      [HS.Switch, HS.MotionSensor, HS.OccupancySensor, HS.SecuritySystem],
      [HC.On, HC.MotionDetected, HC.OccupancyDetected, HC.SecuritySystemCurrentState],
      function () {
        try { onEvent(arguments, variables); }
        catch (e) { console.error(TAG + "событие: " + e.message); }
      });
    log(variables.opts, "подписка на события активна");
  } catch (e) {
    variables.sub = undefined;
    console.warn(TAG + "подписка не создана (" + e.message + "), работаю только по таймеру");
  }
}

function onEvent(args, variables) {
  var options = variables.opts;
  if (!options || !variables.inited) return;
  var uuid = eventServiceUuid(args);
  if (uuid && !isOurSource(uuid, options)) return;

  // Личная разблокировка может быть коротким импульсом — ловим сразу
  if (uuid) {
    var doors = doorUuids(options);
    for (var i = 0; i < doors.length; i++) {
      if (doors[i] && doors[i] === uuid && readBool(uuid, HC.On) === true) armArrival(variables, options, svcName(uuid));
    }
  }
  tick(variables);
}

function setupCron(variables) {
  var sec = clampInt(variables.opts.tickSec, 2, 30, 5);
  var sig = "t" + sec;
  if (variables.cron && variables.cronSig === sig) return;
  if (variables.cron) { try { variables.cron.clear(); } catch (e) {} variables.cron = undefined; }
  variables.cronSig = sig;
  variables.cron = Cron.schedule("*/" + sec + " * * * * *", function () {
    try { tick(variables); }
    catch (e) { console.error(TAG + "cron: " + e.message); }
  });
}

function tick(variables) {
  var options = variables.opts;
  if (!options || !variables.inited) return;
  if (variables.busy) { variables.again = true; return; }
  variables.busy = true;
  try {
    var n = 0;
    do {
      variables.again = false;
      step(variables, options);
      n++;
    } while (variables.again && n < 3);
  } catch (e) {
    console.error(TAG + "tick: " + e.message);
  } finally {
    variables.busy = false;
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// ОСНОВНАЯ ЛОГИКА
// ═══════════════════════════════════════════════════════════════════════════
function step(variables, options) {
  var now = Date.now();
  var dl = variables.dl;
  var s = readAll(options, variables.masterUuid);
  var p = variables.prev || s;
  var i;

  // 0. Мастер изменился, а trigger не пришёл
  if (s.master !== null && s.master !== variables.masterOn) onMasterChange(s.master, variables, options, "состояние выключателя");

  // 1. Режим «Не дома»
  if (s.away === null) s.away = p.away;               // режим недоступен — держим прежний
  var away = (s.away === true);
  var wasAway = (p.away === true);
  if (away && !wasAway) {
    variables.awaySince = now;
    dl.arrival = 0; dl.homeOnline = 0;
    log(options, "режим «Не дома»");
    if (options.awayCamerasOn) setMaster(true, variables, options, "режим «Не дома»");
  } else if (!away && wasAway) {
    variables.awaySince = 0;
    dl.floodOn = zeros(CAM_COUNT); dl.floodOff = zeros(CAM_COUNT);
    log(options, "выход из режима «Не дома» (" + modeTxt(s.sec) + ")");
    if (options.floodOffOnHome) {
      var fl = floodUuids(options);
      for (i = 0; i < fl.length; i++) if (fl[i]) setLight(fl[i], false, options, "выход из «Не дома»");
    }
    if (variables.masterOn) armArrival(variables, options, "выход из «Не дома»");
  }

  // 2. Личная разблокировка двери
  for (i = 0; i < s.doors.length; i++) {
    if (s.doors[i] === true && p.doors[i] !== true) armArrival(variables, options, svcName(doorUuids(options)[i]));
  }

  // 3. Выключение камер после прихода
  if (dl.arrival && now >= dl.arrival) {
    dl.arrival = 0;
    if (variables.masterOn) setMaster(false, variables, options, "приход домой");
  }

  // 4. Прожекторы: «Не дома» + ночь, движение камеры или ДП комнаты
  var fu = floodUuids(options);
  var allow = away && s.night;
  var allowPrev = (p.away === true) && p.night;
  for (i = 0; i < fu.length; i++) {
    if (!fu[i]) continue;
    var det = (s.motion[i] === true || s.occ[i] === true);
    var detPrev = (p.motion[i] === true || p.occ[i] === true);
    if (!allow) {
      dl.floodOn[i] = 0; dl.floodOff[i] = 0;
      if (allowPrev && away) setLight(fu[i], false, options, "наступил день");
      continue;
    }
    if (det && (!detPrev || !allowPrev)) { dl.floodOn[i] = now + intOr(options.floodOnSec, 20) * 1000; dl.floodOff[i] = 0; }
    else if (!det && detPrev) { dl.floodOff[i] = now + intOr(options.floodOffSec, 30) * 1000; dl.floodOn[i] = 0; }
    if (dl.floodOn[i] && now >= dl.floodOn[i]) { dl.floodOn[i] = 0; if (det) setLight(fu[i], true, options, s.motion[i] === true ? "движение" : "присутствие"); }
    if (dl.floodOff[i] && now >= dl.floodOff[i]) { dl.floodOff[i] = 0; if (!det) setLight(fu[i], false, options, "движения и присутствия нет"); }
  }

  // 5. Камеры: в сети / не в сети
  var offNames = [], backNames = [];
  var cu = onlineUuids(options);
  for (i = 0; i < s.cams.length; i++) {
    var cur = s.cams[i];
    var st = variables.cams[i] || { on: cur, since: now, alerted: false };
    if (cur !== null && cur !== st.on) {
      if (cur === true && st.on === false && !away && (!variables.masterOn || options.homeOnlineManual !== false)) {
        dl.homeOnline = now + intOr(options.homeOnlineSec, 35) * 1000;
      }
      log(options, "камера " + svcName(cu[i]) + (cur ? " в сети" : " не в сети"));
      st.on = cur; st.since = now;
    }
    if (away && st.on === false) {
      var from = Math.max(st.since, variables.awaySince || 0);
      if (!st.alerted && now - from >= intOr(options.awayOfflineSec, 60) * 1000) {
        st.alerted = true;
        offNames.push(svcName(cu[i]));
      }
    } else if (st.on === true && st.alerted) {
      st.alerted = false;
      if (away) backNames.push(svcName(cu[i]));
    } else if (!away) {
      st.alerted = false;
    }
    variables.cams[i] = st;
  }
  if (offNames.length) notifyEv(options, "AwayOffline", { cams: offNames.join(", ") });
  if (backNames.length) notifyEv(options, "AwayBack", { cams: backNames.join(", ") });

  // 6. Камера появилась в сети, когда дома и мастер ВЫКЛ
  if (dl.homeOnline && now >= dl.homeOnline) {
    dl.homeOnline = 0;
    var onl = namesWhere(options, s.cams, true);
    if (!away && onl.length) {
      if (!variables.masterOn) notifyEv(options, "HomeOnline", { cams: onl.join(", ") });
      else if (options.homeOnlineManual !== false) notifyEv(options, "ManualOnline", { cams: onl.join(", ") });
    }
  }

  // 7. Проверка ухода в офлайн после выключения мастера
  if (dl.verify && now >= dl.verify) {
    dl.verify = 0;
    if (!variables.masterOn) {
      var still = namesWhere(options, s.cams, true);
      if (still.length) {
        notifyEv(options, "StillOnline", { time: fmtSec(intOr(options.offVerifySec, 300)), cams: still.join(", ") });
      } else {
        log(options, "проверка: все камеры ушли в офлайн");
      }
    }
  }

  // 8. Питание камер не совпадает с мастером
  var pu = powerUuids(options), mis = [];
  for (i = 0; i < s.power.length; i++) {
    if (!pu[i]) continue;
    var v = s.power[i];
    if (v !== variables.masterOn) mis.push(svcName(pu[i]) + (v === null ? " (недоступна)" : (v ? " ВКЛ" : " ВЫКЛ")));
  }
  var mm = variables.mm;
  if (mis.length) {
    if (!mm.since) mm.since = now;
    if (!mm.reported && now - mm.since >= intOr(options.mismatchSec, 60) * 1000) {
      mm.reported = true;
      notifyEv(options, "Mismatch", { master: variables.masterOn ? "ВКЛ" : "ВЫКЛ", cams: mis.join(", ") });
    }
  } else {
    if (mm.reported) notifyEv(options, "MismatchOk", {});
    mm.since = 0; mm.reported = false;
  }

  // 9. Обратная синхронизация: все камеры вручную ВКЛ / ВЫКЛ → мастер
  var allOn = allEq(pu, s.power, true), allOff = allEq(pu, s.power, false);
  if (allOn && !allEq(pu, p.power, true) && !variables.masterOn) setMaster(true, variables, options, "все камеры включены");
  else if (allOff && !allEq(pu, p.power, false) && variables.masterOn) setMaster(false, variables, options, "все камеры выключены");

  variables.prev = s;
}

function armArrival(variables, options, who) {
  var sec = intOr(options.arrivalOffSec, 30);
  variables.dl.arrival = Date.now() + sec * 1000;
  log(options, "приход: " + who + (variables.masterOn ? ", камеры выключатся через " + sec + " с" : ", камеры уже выключены"));
}

// ═══════════════════════════════════════════════════════════════════════════
// УВЕДОМЛЕНИЯ
// ═══════════════════════════════════════════════════════════════════════════
function notifyEv(options, key, vals) {
  notify(options, fmtMsg(txt(options, "msg" + key), vals), fmtMsg(txt(options, "voice" + key), vals));
}

// Отправка асинхронно: sendTG и Яндекс делают синхронные HTTP-запросы и не должны тормозить логику
function notify(options, text, phrase) {
  text = trimStr(text);
  phrase = trimStr(phrase);
  if (!text && !phrase) return;                       // пусто — событие не сообщается
  if (text) console.warn(TAG + text);
  setTimeout(function () {
    if (text && options.tgEnabled) {
      try {
        if (typeof global !== "undefined" && global && typeof global.sendTG === "function") {
          global.sendTG(text);
        } else {
          Notify.text(String(text).replace(/_/g, "\\_")).to(trimStr(options.tgChannel) || "telegram_1").send();
        }
      } catch (e) { console.error(TAG + "Telegram: " + e.message); }
    }
    var web = trimStr(options.webChannel);
    if (text && web) {
      try { Notify.text(text).to(web).send(); }
      catch (e) { console.error(TAG + "push: " + e.message); }
    }
    if (phrase && options.voiceEnabled) say(options, phrase);
  }, 0);
}

function say(options, phrase) {
  try {
    var ya = (typeof global !== "undefined" && global) ? global.YAActions : null;
    if (!ya || typeof ya.sayPhrase !== "function") {
      console.warn(TAG + "колонка: global.YAActions не найден — включён ли сценарий Yandex for Sprut?");
      return;
    }
    var spk = trimStr(options.voiceSpeaker) || "Моя колонка";
    var v1 = volOrNull(options.voiceVolume), v2 = volOrNull(options.voiceVolumeAfter);
    var res;
    if ((v1 !== null || v2 !== null) && typeof ya.sayPhraseWithVolume === "function") res = ya.sayPhraseWithVolume(spk, phrase, v1, v2);
    else res = ya.sayPhrase(spk, phrase);
    log(options, "колонка «" + spk + "»: " + phrase + (res === false ? " — ОШИБКА (см. лог YAActions)" : ""));
  } catch (e) { console.error(TAG + "колонка: " + e.message); }
}

function volOrNull(v) {
  var n = parseInt(v, 10);
  return (isNaN(n) || n < 0) ? null : (n > 10 ? 10 : n);
}

// ═══════════════════════════════════════════════════════════════════════════
// ЧТЕНИЕ
// ═══════════════════════════════════════════════════════════════════════════
function readAll(options, masterUuid) {
  var sec = readNum(options.securityService, HC.SecuritySystemCurrentState);
  var i, doors = [], power = [], cams = [], motion = [], occ = [];
  var du = doorUuids(options), pu = powerUuids(options), cu = onlineUuids(options), mu = motionUuids(options), ou = occUuids(options);
  for (i = 0; i < du.length; i++) doors.push(du[i] ? readBool(du[i], HC.On) : null);
  for (i = 0; i < pu.length; i++) power.push(pu[i] ? readBool(pu[i], HC.On) : null);
  for (i = 0; i < cu.length; i++) cams.push(cu[i] ? readBool(cu[i], HC.C_Online) : null);
  for (i = 0; i < mu.length; i++) motion.push(mu[i] ? readBool(mu[i], HC.MotionDetected) : null);
  for (i = 0; i < ou.length; i++) occ.push(ou[i] ? readBool(ou[i], HC.OccupancyDetected) : null);
  var dn = trimStr(options.dayNightService) ? readBool(options.dayNightService, HC.On) : null;
  var night = (dn === null) ? true : (options.nightWhenOn === false ? !dn : dn);
  return {
    sec: sec,
    away: (sec === null) ? null : (sec === 1),
    master: masterUuid ? readBool(masterUuid, HC.On) : null,
    motion: motion, occ: occ, night: night,
    doors: doors, power: power, cams: cams
  };
}

function readRaw(uuid, charType) {
  uuid = trimStr(uuid);
  if (!uuid) return null;
  try {
    var svc = getService(uuid);
    if (!svc) return null;
    var c = svc.getCharacteristic(charType);
    if (!c) return null;
    var v = c.getValue();
    return (v === undefined) ? null : v;
  } catch (e) {
    return null;
  }
}

function readBool(uuid, charType) { return toBool(readRaw(uuid, charType)); }

function readNum(uuid, charType) {
  var v = readRaw(uuid, charType);
  if (v === null) return null;
  var n = parseInt(v, 10);
  return isNaN(n) ? null : n;
}

function toBool(v) {
  if (typeof v === "object" && v !== null && v.value !== undefined) v = v.value;
  if (v === true || v === 1 || v === "1" || v === "true") return true;
  if (v === false || v === 0 || v === "0" || v === "false") return false;
  return null;
}

var CAM_COUNT = 7;
function zeros(n) {
  var r = [];
  for (var i = 0; i < n; i++) r.push(0);
  return r;
}
function camOpts(o, key) {
  var r = [];
  for (var i = 1; i <= CAM_COUNT; i++) r.push(trimStr(o["cam" + i + key]));
  return r;
}
function powerUuids(o)  { return camOpts(o, "Power"); }
function onlineUuids(o) { return camOpts(o, "Online"); }
function motionUuids(o) { return camOpts(o, "Motion"); }
function floodUuids(o)  { return camOpts(o, "Flood"); }
function occUuids(o)    { return camOpts(o, "Occ"); }
function doorUuids(o)   { return [trimStr(o.door1), trimStr(o.door2), trimStr(o.door3)]; }

function isOurSource(uuid, o) {
  var list = powerUuids(o).concat(doorUuids(o), motionUuids(o), occUuids(o), [trimStr(o.dayNightService), trimStr(o.securityService)]);
  for (var i = 0; i < list.length; i++) if (list[i] && list[i] === uuid) return true;
  return false;
}

function eventServiceUuid(args) {
  for (var i = 0; i < args.length; i++) {
    var a = args[i];
    if (a === null || a === undefined || typeof a !== "object") continue;
    try {
      if (typeof a.getCharacteristic === "function" && typeof a.getUUID === "function") return String(a.getUUID());
      if (typeof a.getService === "function") {
        var s = a.getService();
        if (s && typeof s.getUUID === "function") return String(s.getUUID());
      }
    } catch (e) {}
  }
  return null;
}

function allEq(uuids, vals, want) {
  var any = false;
  for (var i = 0; i < uuids.length; i++) {
    if (!uuids[i]) continue;
    any = true;
    if (vals[i] !== want) return false;
  }
  return any;
}

function namesWhere(options, cams, want) {
  var cu = onlineUuids(options), r = [];
  for (var i = 0; i < cams.length; i++) if (cu[i] && cams[i] === want) r.push(svcName(cu[i]));
  return r;
}

function getService(uuid) {
  if (!uuid || uuid === "") return null;
  try {
    var parts = String(uuid).split(".");
    var acc = Hub.getAccessory(parts[0]);
    return acc ? acc.getService(parts[1]) : null;
  } catch (e) {
    return null;
  }
}

function svcName(uuid) {
  var svc = getService(uuid);
  if (!svc) return String(uuid || "?");
  try {
    var acc = svc.getAccessory();
    var an = acc.getName(), sn = svc.getName();
    if (svc.getType() === HS.AccessoryInformation || !sn || an === sn) return an;
    return an + " " + sn;
  } catch (e) {
    return String(uuid);
  }
}

function buildLists() {
  var camTypes = [];
  if (HS.CameraRTPStreamManagement !== undefined) camTypes.push(HS.CameraRTPStreamManagement);
  if (HS.CameraOperatingMode !== undefined) camTypes.push(HS.CameraOperatingMode);
  camTypes.push(HS.MotionSensor);

  var r = { sw: [], cam: [], camAll: [], motion: [], occ: [], light: [], sec: [] };
  Hub.getAccessories().forEach(function (acc) {
    var accName = acc.getName();
    var roomName = acc.getRoom() ? acc.getRoom().getName() : "";
    var svcs = acc.getServices();
    var isCam = false, infoItem = null;
    svcs.forEach(function (svc) {
      var t = svc.getType();
      if (camTypes.indexOf(t) >= 0) isCam = true;
      var svcName = svc.getName();
      var nm = (t === HS.AccessoryInformation || accName === svcName) ? accName : accName + " " + svcName;
      var label = roomName + " → " + nm + " (" + svc.getUUID() + ")";
      var item = { name: { ru: label, en: label }, value: svc.getUUID() };
      if (t === HS.Switch && svc.getCharacteristic(HC.On)) r.sw.push(item);
      else if (t === HS.MotionSensor) r.motion.push(item);
      else if (t === HS.OccupancySensor) r.occ.push(item);
      else if (t === HS.Lightbulb && svc.getCharacteristic(HC.On)) r.light.push(item);
      else if (t === HS.SecuritySystem) r.sec.push(item);
      else if (t === HS.AccessoryInformation && svc.getCharacteristic(HC.C_Online)) infoItem = item;
    });
    if (infoItem) { r.camAll.push(infoItem); if (isCam) r.cam.push(infoItem); }
  });
  if (!r.cam.length) r.cam = r.camAll;
  var out = {};
  ["sw", "cam", "motion", "occ", "light", "sec"].forEach(function (k) {
    r[k].sort(function (a, b) { return a.name.ru.localeCompare(b.name.ru); });
    out[k] = [{ name: { ru: "Не выбрано", en: "Not selected" }, value: "" }].concat(r[k]);
  });
  return out;
}

// ═══════════════════════════════════════════════════════════════════════════
// УТИЛИТЫ
// ═══════════════════════════════════════════════════════════════════════════
function modeTxt(sec) {
  return sec === 0 ? "Дома" : sec === 1 ? "Не дома" : sec === 2 ? "Ночь" : (sec === null ? "н/д" : String(sec));
}

// Тексты по умолчанию — если опции ещё нет в сохранённых настройках (пустая строка = выключено)
var MSG_DEF = {
  voiceMismatchOk: "",
  voiceMismatch: "",
  voiceManualOnline: "Камеры включены и в сети",
  voiceAwayBack: "",
  voiceAwayOffline: "Камеры не в сети, хотя никого нет дома",
  msgManualOnline: "🎦 Камеры включены вручную и в сети ✅: {cams}",
  msgAwayOffline: "🎦 Камеры не в сети 🚫, хотя никого нет дома 🏚️: {cams}",
  msgAwayBack: "🎦 Камеры снова в сети ✅: {cams}",
  msgHomeOnline: "🎦 Камеры появились в сети ✅, хотя кто-то есть дома 🏠: {cams}",
  voiceHomeOnline: "Камеры появились в сети, хотя кто-то есть дома",
  msgStillOnline: "🎦 Камеры остаются в сети ✅ через {time} после выключения: {cams}",
  voiceStillOnline: "Камеры всё ещё в сети после выключения",
  msgMismatch: "⚠️ Мастер камер {master}, но питание не совпадает: {cams}",
  msgMismatchOk: "✅ Питание камер снова совпадает с мастером"
};
function txt(o, key) {
  var v = o ? o[key] : undefined;
  return (v === undefined || v === null) ? MSG_DEF[key] : String(v);
}

function fmtMsg(tpl, vals) {
  var t = (tpl === undefined || tpl === null) ? "" : String(tpl);
  for (var k in vals) {
    if (vals.hasOwnProperty(k)) t = t.split("{" + k + "}").join(String(vals[k]));
  }
  return t;
}

function fmtSec(s) { return (s % 60 === 0) ? (s / 60) + " мин" : s + " с"; }

function intOr(v, def) {
  var n = parseInt(v, 10);
  return isNaN(n) || n < 0 ? def : n;
}

function clampInt(v, lo, hi, def) {
  var n = parseInt(v, 10);
  if (isNaN(n)) n = def;
  return n < lo ? lo : (n > hi ? hi : n);
}

function trimStr(s) { return s ? String(s).replace(/^\s+|\s+$/g, "") : ""; }

function log(options, msg) {
  if (options && options.logEnabled) console.info(TAG + msg);
}
